create temp table demo (owner uuid, slug text, bio text, cover text, website text);
insert into demo values
  ('75ec667d-ca56-5c1b-85b6-9be9cc448f6e', 'tiwaras-house', 'The house that started the platform. Tiwára has spent eight years perfecting protective styles that last — every appointment starts with a consultation and ends with hair you don''t have to think about for weeks.', 'demo/stylists/w160944.jpg', 'https://tiwarashouse.com'),
  ('b03ff09f-c011-5b7b-b33c-48ed9d19dbae', 'amara-beauty', 'Colour-brave boho and goddess braids with a soft finish. Amara works from a private studio in Hulme.', 'demo/stylists/w161154.jpg', null),
  ('8381fce8-6eec-5922-bf3f-826d9ad69983', 'naturallynia', 'Healthy-hair-first natural care. Nia specialises in curl definition, trims and treatments for 3c–4c hair.', 'demo/stylists/IMG_0013.jpg', 'https://naturallynia.co.uk'),
  ('196e0d11-6c3d-588c-b586-d1e932b68863', 'braid-bar-mcr', 'Fast hands, clean parts. Walk-out-ready fulani and stitch styles in the middle of town.', 'demo/stylists/w161244.jpg', null),
  ('08377e18-082b-55cb-bff4-f02065231f15', 'crowned-by-kemi', 'Statement colour and boho texture. Kemi mixes custom tones for every install.', 'demo/stylists/w161942.jpg', null),
  ('b9df8b6f-610e-5b83-8726-78dbe5c0516d', 'studio-zuri', 'Precision installs and short knotless shapes in a calm Salford studio.', 'demo/stylists/w162031.jpg', null),
  ('476c50dd-910a-5c30-abe3-67f44b11b693', 'locd-and-lovely', 'Locs only, done properly — retwists, repairs and styles that respect your roots.', 'demo/stylists/w161512.jpg', null),
  ('1f28d104-108f-5c83-a100-431a60d5628d', 'silk-and-roots', 'Sleek finishes and healthy stretches — silk presses that survive Manchester weather.', 'demo/stylists/w160524.jpg', null);

update public.stylists
set slug = demo.slug, bio = demo.bio, cover_path = demo.cover, website = demo.website,
  availability_confirmed_at = now(), profile_confirmed_at = now()
from demo where stylists.owner_id = demo.owner;

delete from public.services where stylist_id in (select id from public.stylists where owner_id in (select owner from demo));
delete from public.stylist_categories where stylist_id in (select id from public.stylists where owner_id in (select owner from demo));

